import React, { useContext, useState } from 'react';
import axios from 'axios';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import MyContext from '../contexts/MyContext';
import { getCustomerAppUrl } from '../utils/customerAppUrl';
import '../css/LoginComponent.css';

const roleHome = {
  admin: '/admin/report',
  receptionist: '/admin/reception',
  kitchen: '/admin/kitchen'
};

function Login() {
  const context = useContext(MyContext);
  const navigate = useNavigate();
  const location = useLocation();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [guestName, setGuestName] = useState('');
  const [loginMode, setLoginMode] = useState('login');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const tableValue = new URLSearchParams(location.search).get('table') || '';
  const tableNumber = Number(String(tableValue).match(/\d+/)?.[0]);
  const tableNo = Number.isInteger(tableNumber) && tableNumber >= 1 && tableNumber <= 12
    ? String(tableNumber).padStart(2, '0')
    : '';

  const getOrCreateGuestId = () => {
    const existingId = localStorage.getItem('guestId');
    if (existingId) return existingId;
    const newId = window.crypto?.randomUUID
      ? window.crypto.randomUUID()
      : `guest-${Date.now()}-${Math.random().toString(36).slice(2, 14)}`;
    localStorage.setItem('guestId', newId);
    return newId;
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');

    if (!username.trim() || !password) {
      setError('Vui lòng nhập tên đăng nhập và mật khẩu.');
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await axios.post('/api/admin/login', {
        username: username.trim(),
        password
      });
      const { token, role, username: accountName } = response.data || {};

      if (!token || (role !== 'customer' && !roleHome[role])) {
        setError(response.data?.message || 'Máy chủ trả về thông tin đăng nhập không hợp lệ.');
        return;
      }

      const signedInUsername = accountName || username.trim();
      context.signIn({ token, role, username: signedInUsername });

      if (role === 'customer') {
        window.location.assign(getCustomerAppUrl({ token, username: signedInUsername, tableNo }));
        return;
      }

      navigate(roleHome[role], { replace: true });
    } catch (requestError) {
      setError(
        requestError.response?.data?.message ||
        'Không thể kết nối đến máy chủ. Vui lòng kiểm tra máy chủ rồi thử lại.'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGuestContinue = async (event) => {
    event.preventDefault();
    const name = guestName.trim();
    if (!name) {
      setError('Vui lòng nhập tên của bạn để nhân viên biết người đặt món.');
      return;
    }

    setError('');
    setIsSubmitting(true);
    try {
      const guestId = getOrCreateGuestId();
      const response = await axios.post('/api/admin/guest-session', { guestId, name });
      const token = response.data?.token;
      if (!token) {
        setError(response.data?.message || 'Không thể mở phiên khách lúc này.');
        return;
      }

      context.signIn({ token, role: 'customer', username: name });
      localStorage.removeItem('guestId');
      window.location.assign(getCustomerAppUrl({ token, username: name, tableNo }));
    } catch (requestError) {
      setError(requestError.response?.data?.message || 'Không thể kết nối đến máy chủ. Vui lòng thử lại.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="login-container">
      {/* Header thương hiệu nhà hàng */}
      <div className="login-header">
        <h2>Nhà hàng Văn Lang</h2>
        <p>Vietnamese Restaurant</p>
      </div>

      {/* Card chứa form đăng nhập */}
      <div className="login-card">
        <div className="login-mode-tabs" role="tablist" aria-label="Chọn cách vào thực đơn">
          <button
            type="button"
            role="tab"
            aria-selected={loginMode === 'login'}
            className={loginMode === 'login' ? 'active' : ''}
            onClick={() => { setLoginMode('login'); setError(''); }}
          >
            Đăng nhập
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={loginMode === 'guest'}
            className={loginMode === 'guest' ? 'active' : ''}
            onClick={() => { setLoginMode('guest'); setError(''); }}
          >
            Khách
          </button>
        </div>

        {loginMode === 'login' ? <>
        <h3>Đăng nhập</h3>
        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <input
              type="text"
              autoComplete="username"
              placeholder="Tên đăng nhập hoặc số điện thoại"
              value={username}
              onChange={(event) => setUsername(event.target.value)}
            />
          </div>
          <div className="input-group">
            <input
              type="password"
              autoComplete="current-password"
              placeholder="Mật khẩu"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
            />
          </div>

          {error && <p role="alert" style={{ color: '#b42318', fontSize: '13px', marginBottom: '10px' }}>{error}</p>}

          <button type="submit" disabled={isSubmitting} className="btn-submit">
            {isSubmitting ? 'ĐĂNG NHẬP…' : 'Đăng Nhập'}
          </button>
        </form>

        <div className="switch-auth">
          Bạn chưa có tài khoản? <Link to="/register">Đăng ký</Link>
        </div>
        </> : <>
          <h3>Tiếp tục với tư cách khách</h3>
          {tableNo && <p className="guest-table-label">Thực đơn dành cho <strong>Bàn {tableNo}</strong></p>}
          <form onSubmit={handleGuestContinue}>
            <div className="input-group">
              <input
                type="text"
                autoComplete="name"
                maxLength="100"
                placeholder="Tên của bạn"
                value={guestName}
                onChange={(event) => setGuestName(event.target.value)}
              />
            </div>
            {error && <p role="alert" className="login-error">{error}</p>}
            <button type="submit" disabled={isSubmitting} className="btn-submit">
              {isSubmitting ? 'ĐANG MỞ THỰC ĐƠN…' : 'Tiếp tục với tư cách khách'}
            </button>
          </form>
          <p className="guest-help-text">Tên này sẽ được dùng để ghi nhận đơn hàng của bạn.</p>
        </>}
      </div>

      {/* Footer */}
      <div className="login-footer">
        <div>Nhà hàng Văn Lang</div>
        <div>© 2026</div>
      </div>
    </div>
  );
}

export default Login;
